// Pega o item de entrada.
const inputItem = $input.first().json;

// Etapa 1: Acessar a propriedade correta ('output') para obter a string bruta.
const rawOutputString = inputItem.output;

/*
  Etapa 2: Limpar a string.
  - Remove o "```json\n" do começo.
  - Remove o "\n```" do final.
  - .trim() remove espaços em branco extras, por segurança.
*/
const cleanedJsonString = rawOutputString
  .replace("```json\n", "")
  .replace("\n```", "")
  .trim();

// Etapa 3: Agora que a string está limpa, fazer o parse.
const reportDataObject = JSON.parse(cleanedJsonString);

// Etapa 4: Retornar o objeto JavaScript pronto para ser usado.
return reportDataObject;

// =================================================================
// FUNÇÕES AUXILIARES PARA GERAR SEÇÕES DINÂMICAS DO HTML
// =================================================================

/**
 * Gera o HTML para a seção de Pontos Críticos.
 * Lida com o caso de haver ou não pendências.
 */
function gerarHtmlPontosCriticos(pontosCriticosArray) {
  if (!pontosCriticosArray || pontosCriticosArray.length === 0) {
    // Cenário POSITIVO: Nenhum ponto crítico
    return `
      <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; background-color: #dff0d8; border-left: 4px solid #3c763d;">
        <tr>
          <td style="padding: 20px;">
            <p style="margin: 0; font-size: 16px; color: #3c763d; font-weight: bold;">Nenhum ponto crítico identificado.</p>
            <p style="margin: 5px 0 0; font-size: 14px; color: #3c763d;">Todas as operações estão fluindo normalmente.</p>
          </td>
        </tr>
      </table>
    `;
  }

  // Cenário de ALERTA: Monta um card para cada navio com problema
  const cardsHtml = pontosCriticosArray.map(ponto => {
    const isCritical = ponto.pendencias.some(p => ['bloqueado', 'cancelado', 'rejeitado'].includes(p.status));
    const headerColor = isCritical ? '#c62828' : '#ff8f00';
    const pendenciasRows = ponto.pendencias.map(pend => `
      <tr>
        <td style="padding: 10px; border-top: 1px solid #eee; font-size: 14px;">${pend.orgao}</td>
        <td style="padding: 10px; border-top: 1px solid #eee; font-weight: bold; font-size: 14px; color: ${headerColor}; text-transform: capitalize;">${pend.status.replace('_', ' ')}</td>
        <td style="padding: 10px; border-top: 1px solid #eee; font-size: 14px;">${pend.detalhe}</td>
      </tr>
    `).join('');

    return `
      <div style="border-radius: 8px; margin-bottom: 20px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); border: 1px solid #ddd;">
          <div style="padding: 15px 20px; color: #fff; font-weight: 700; font-size: 1.2em; background-color: ${headerColor}; border-top-left-radius: 8px; border-top-right-radius: 8px;">
              NAVIO: ${ponto.identificadorNavio}
          </div>
          <div style="padding: 15px; background: #fff;">
              <table border="0" cellpadding="0" cellspacing="0" width="100%">
                  ${pendenciasRows}
              </table>
          </div>
      </div>
    `;
  }).join('');
  return cardsHtml;
}

/**
 * Gera o HTML para a seção de Próximas Operações.
 */
function gerarHtmlProximasOperacoes(proximasOperacoesObj) {
  if (!proximasOperacoesObj || !proximasOperacoesObj.chegadasConfirmadas || proximasOperacoesObj.chegadasConfirmadas.length === 0) {
    return '<p style="font-size: 15px; color: #555;">Nenhuma próxima operação agendada nos dados atuais.</p>';
  }

  const rows = proximasOperacoesObj.chegadasConfirmadas.map(op => `
    <tr>
      <td style="padding: 12px; border-top: 1px solid #dddddd; font-size: 15px; color: #555;">${op.identificadorNavio}</td>
      <td style="padding: 12px; border-top: 1px solid #dddddd; font-size: 15px; color: #555;">${op.dataPrevisaoChegadaOriginal}</td>
    </tr>
  `).join('');

  return `
    <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; border: 1px solid #dddddd;">
      <thead>
        <tr style="background-color: #f2f2f2;">
          <th style="padding: 12px; text-align: left; font-size: 14px; color: #333;">Identificador do Navio</th>
          <th style="padding: 12px; text-align: left; font-size: 14px; color: #333;">Data Prevista da Chegada</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

/**
 * Gera o HTML para a tabela de Visão Geral.
 */
function gerarHtmlVisaoGeral(visaoGeralObj) {
  if (!visaoGeralObj || !visaoGeralObj.status) return '';

  let rowsHtml = '';
  for (const [key, value] of Object.entries(visaoGeralObj.status)) {
      rowsHtml += `
           <tr>
              <td style="padding: 8px; font-size: 14px; color: #333; border-bottom: 1px solid #eee; text-transform: capitalize;">${key.replace(/_/g, ' ')}:</td>
              <td style="padding: 8px; font-size: 14px; color: #333; border-bottom: 1px solid #eee; text-align: right; font-weight: bold;">${value}</td>
          </tr>
      `;
  }
  return `<table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse;">${rowsHtml}</table>`;
}


// =================================================================
// LÓGICA PRINCIPAL DO NÓ "CODE"
// =================================================================

const allItems = $input.all();
let reportsHtml = '';

// Itera sobre cada item/relatório recebido do n8n
for (const item of allItems) {
  const reportData = item.json;

  // Chama as funções auxiliares para construir as seções dinâmicas
  const pontosCriticosHtml = gerarHtmlPontosCriticos(reportData.pontosCriticos);
  const proximasOperacoesHtml = gerarHtmlProximasOperacoes(reportData.proximasOperacoes);
  const visaoGeralHtml = gerarHtmlVisaoGeral(reportData.visaoGeral);

  // Concatena o HTML de um relatório completo
  reportsHtml += `
    <table align="center" border="0" cellpadding="0" cellspacing="0" width="600" style="border-collapse: collapse; background-color: #ffffff; border: 1px solid #dddddd; margin-bottom: 25px;">
        <tr>
            <td align="center" style="padding: 30px 20px; background-color: #1a237e; color: #ffffff;">
                <h1 style="margin: 0; font-size: 24px; font-weight: bold;">${reportData.relatorioInfo.titulo}</h1>
                <p style="margin: 5px 0 0; font-size: 14px;">Gerado em: ${reportData.relatorioInfo.dataGeracao}</p>
            </td>
        </tr>
        <tr>
            <td style="padding: 30px 30px 20px 30px;">
                <h2 style="font-size: 20px; color: #1a237e; margin-top: 0;">Sumário Executivo</h2>
                <p style="margin: 0; font-size: 16px; line-height: 1.6; color: #333333;">${reportData.sumarioExecutivo}</p>
            </td>
        </tr>
        <tr>
            <td style="padding: 0 30px 30px 30px;">
                 <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; background-color: #e8eaf6; border-left: 4px solid #3f51b5;">
                    <tr>
                        <td style="padding: 15px 20px;">
                            <p style="margin: 0; font-size: 15px; color: #1a237e; font-weight: bold;">Notificação: ${reportData.push_notification}</p>
                        </td>
                    </tr>
                 </table>
            </td>
        </tr>
        <tr>
            <td style="padding: 0 30px 20px 30px;">
                <h2 style="font-size: 20px; color: #1a237e; margin-top: 0;">Pontos Críticos</h2>
                ${pontosCriticosHtml}
            </td>
        </tr>
        <tr>
            <td style="padding: 10px 30px 20px 30px;">
                <h2 style="font-size: 20px; color: #1a237e; margin-top: 0;">Próximas Operações Agendadas</h2>
                ${proximasOperacoesHtml}
            </td>
        </tr>
        <tr>
            <td style="padding: 10px 30px 30px 30px;">
                <h2 style="font-size: 20px; color: #1a237e; margin-top: 0;">Visão Geral do Terminal</h2>
                ${visaoGeralHtml}
            </td>
        </tr>
    </table>
  `;
}

// Monta o documento HTML final
const finalHtml = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Relatório de Situação Operacional</title>
</head>
<body style="margin: 0; padding: 0; background-color: #f4f7f9; font-family: Arial, Helvetica, sans-serif;">
    <table border="0" cellpadding="0" cellspacing="0" width="100%">
        <tr>
            <td style="padding: 20px 0;">
                ${reportsHtml} </td>
        </tr>
        <tr>
            <td align="center" style="padding: 20px; color: #888888; font-size: 12px;">
                <p style="margin: 0;">Este é um relatório automático gerado pelo CascadeSightAI.</p>
            </td>
        </tr>
    </table>
</body>
</html>`;

// Retorna o HTML completo para ser usado no próximo nó (ex: Send Email)
return {
  json: {
    html: finalHtml,
    push_notification: $input.first().json.push_notification
  }
};
